# Solution L6-5: Top 2 bridge EI nodes and cautious interpretation
source("R/_setup.R"); suppressPackageStartupMessages({ library(bootnet); library(networktools) })
log_open("sol_L6-5_log.txt")
# Same as R/L6-5.R: Bridge centrality uses 9 items at T1 from course data (the 16 items generated by genGGM have no genuine community structure)
dat <- read_course_data()
t1 <- dat[, vars_t(1)]; colnames(t1) <- items
net <- estimateNetwork(t1, default = "EBICglasso", tuning = .5, corMethod = "cor_auto", verbose = FALSE)
b <- bridge(net$graph, communities = ifelse(items %in% lone_items, "Loneliness", "Depression"))
top <- sort(b$`Bridge Expected Influence (1-step)`, decreasing = TRUE)[1:2]; print(round(top, 3))
cat("Cautious interpretation:", names(top)[1], "(\"", item_en[names(top)[1]], "\") and", names(top)[2], "(\"", item_en[names(top)[2]], "\")",
    "exhibit the strongest contemporaneous connections to the other construct (cross-sectional, associational). They serve as candidate \"bridge points\" connecting loneliness and depression,\n",
    "but this does not constitute causal evidence, nor does it indicate temporal directionality; stability must also be assessed (bootnet).\n")
log_close()
